"""Small MLIR-style IR used by the exercises in this repository."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Callable, Iterable, Iterator, Optional, Sequence


class Type:
    """Base class for IR types."""

    def __str__(self) -> str:
        raise NotImplementedError


@dataclass(frozen=True)
class IntegerType(Type):
    """Signless integer type."""

    width: int

    def __post_init__(self) -> None:
        if self.width <= 0:
            raise ValueError(f"integer width must be positive, got {self.width}")

    def __str__(self) -> str:
        return f"i{self.width}"

    def mask(self, value: int) -> int:
        return value & ((1 << self.width) - 1)

    def as_signed(self, value: int) -> int:
        masked = self.mask(value)
        sign_bit = 1 << (self.width - 1)
        return masked - (1 << self.width) if masked & sign_bit else masked


@dataclass(frozen=True)
class ClockType(Type):
    """Clock type used by the seq dialect."""

    def __str__(self) -> str:
        return "!seq.clock"


@dataclass(frozen=True)
class OpaqueType(Type):
    """Fallback type for unsupported textual spellings."""

    spelling: str

    def __str__(self) -> str:
        return self.spelling


@dataclass(frozen=True)
class FunctionType(Type):
    """Function signature type."""

    inputs: tuple[Type, ...]
    results: tuple[Type, ...]

    def __str__(self) -> str:
        inputs = ", ".join(str(value) for value in self.inputs)
        if not self.results:
            results = "()"
        elif len(self.results) == 1:
            results = str(self.results[0])
        else:
            results = f"({', '.join(str(value) for value in self.results)})"
        return f"({inputs}) -> {results}"


def parse_type(text: str) -> Type:
    """Parse the minimal type surface used by the samples."""

    text = text.strip()
    if not text:
        raise ValueError("cannot parse empty type")
    if text.startswith("i") and text[1:].isdigit():
        return IntegerType(int(text[1:]))
    if text == "!seq.clock":
        return ClockType()
    return OpaqueType(text)


class Value:
    """SSA value or block argument."""

    def __init__(
        self,
        name: str,
        value_type: Optional[Type] = None,
        owner: Optional[Any] = None,
        *,
        placeholder: bool = False,
    ) -> None:
        if not name.startswith("%"):
            name = f"%{name}"
        self.name = name
        self.type = value_type
        self.owner = owner
        self.placeholder = placeholder
        self.uses: list[tuple["Operation", int]] = []

    def __repr__(self) -> str:
        suffix = f": {self.type}" if self.type is not None else ""
        return f"{self.name}{suffix}"

    def add_use(self, op: "Operation", index: int) -> None:
        self.uses.append((op, index))

    def replace_all_uses_with(self, replacement: "Value") -> None:
        for op, index in list(self.uses):
            op.replace_operand(index, replacement)
        self.uses.clear()

    @property
    def use_count(self) -> int:
        return len(self.uses)


class Operation:
    """Generic operation with MLIR-like nesting and SSA results."""

    def __init__(
        self,
        name: str,
        operands: Optional[Sequence[Value]] = None,
        results: Optional[Sequence[Value]] = None,
        result_types: Optional[Sequence[Type]] = None,
        result_names: Optional[Sequence[str]] = None,
        attributes: Optional[dict[str, Any]] = None,
        regions: Optional[Sequence["Region"]] = None,
        successors: Optional[Sequence["Block"]] = None,
    ) -> None:
        self.name = name
        self.attributes: dict[str, Any] = dict(attributes or {})
        self.parent: Optional[Block] = None
        self.regions: list[Region] = list(regions or [])
        for region in self.regions:
            region.parent = self
        self.successors: list[Block] = list(successors or [])
        self.operands: list[Value] = []
        for operand in operands or []:
            self.add_operand(operand)
        if results is not None:
            self.results = list(results)
            for value in self.results:
                value.owner = self
                value.placeholder = False
        else:
            result_types = list(result_types or [])
            result_names = list(result_names or [f"%r{index}" for index in range(len(result_types))])
            if len(result_types) != len(result_names):
                raise ValueError("result_types and result_names must have the same length")
            self.results = [
                Value(name, value_type, self)
                for name, value_type in zip(result_names, result_types)
            ]

    def __repr__(self) -> str:
        return f"Operation({self.name})"

    def add_operand(self, value: Value) -> None:
        self.operands.append(value)
        value.add_use(self, len(self.operands) - 1)

    def replace_operand(self, index: int, value: Value) -> None:
        old = self.operands[index]
        old.uses = [(op, i) for op, i in old.uses if not (op is self and i == index)]
        self.operands[index] = value
        value.add_use(self, index)

    def walk(self, visitor: Callable[["Operation"], None]) -> None:
        visitor(self)
        for region in self.regions:
            region.walk(visitor)

    def detach(self) -> None:
        if self.parent is not None:
            self.parent.erase(self)

    @property
    def has_side_effects(self) -> bool:
        return self.name in {"return", "cf.br", "cf.cond_br", "hw.output", "seq.compreg"}

    @property
    def result(self) -> Optional[Value]:
        return self.results[0] if self.results else None

    def format(self) -> Optional[str]:
        """Allow subclasses to provide a custom textual form."""

        return None


class Block:
    """A sequence of operations with optional block arguments."""

    def __init__(
        self,
        label: Optional[str] = None,
        arguments: Optional[Sequence[Value]] = None,
    ) -> None:
        self.label = label
        self.arguments: list[Value] = list(arguments or [])
        for arg in self.arguments:
            arg.owner = self
            arg.placeholder = False
        self.operations: list[Operation] = []
        self.parent: Optional[Region] = None

    def __iter__(self) -> Iterator[Operation]:
        return iter(self.operations)

    def append(self, op: Operation) -> None:
        op.parent = self
        self.operations.append(op)

    def insert(self, index: int, op: Operation) -> None:
        op.parent = self
        self.operations.insert(index, op)

    def erase(self, op: Operation) -> None:
        self.operations.remove(op)
        op.parent = None

    def walk(self, visitor: Callable[[Operation], None]) -> None:
        for op in list(self.operations):
            op.walk(visitor)

    def is_empty(self) -> bool:
        return not self.operations


class Region:
    """A region owns a list of blocks."""

    def __init__(self, blocks: Optional[Sequence[Block]] = None) -> None:
        self.blocks: list[Block] = list(blocks or [])
        self.parent: Optional[Operation] = None
        for block in self.blocks:
            block.parent = self

    def append(self, block: Block) -> None:
        block.parent = self
        self.blocks.append(block)

    def walk(self, visitor: Callable[[Operation], None]) -> None:
        for block in list(self.blocks):
            block.walk(visitor)

    @property
    def entry(self) -> Block:
        if not self.blocks:
            raise ValueError("region has no blocks")
        return self.blocks[0]


class ModuleOp(Operation):
    """Top-level builtin.module operation."""

    def __init__(self, body: Optional[Region] = None) -> None:
        if body is None:
            body = Region([Block(label=None)])
        super().__init__("builtin.module", regions=[body])

    @property
    def body(self) -> Block:
        return self.regions[0].entry

    def symbols(self) -> dict[str, Operation]:
        result: dict[str, Operation] = {}
        for op in self.body.operations:
            symbol = op.attributes.get("sym_name")
            if symbol:
                result[symbol] = op
        return result

    def get_symbol(self, name: str) -> Optional[Operation]:
        return self.symbols().get(name)


class FuncOp(Operation):
    """Function-like operation with one body region."""

    def __init__(
        self,
        symbol_name: str,
        arg_names: Sequence[str],
        arg_types: Sequence[Type],
        result_types: Sequence[Type],
    ) -> None:
        arguments = [Value(name, typ) for name, typ in zip(arg_names, arg_types)]
        body = Region([Block(arguments=arguments)])
        super().__init__(
            "func.func",
            attributes={
                "sym_name": symbol_name,
                "function_type": FunctionType(tuple(arg_types), tuple(result_types)),
            },
            regions=[body],
        )

    @property
    def symbol_name(self) -> str:
        return str(self.attributes["sym_name"])

    @property
    def function_type(self) -> FunctionType:
        return self.attributes["function_type"]

    @property
    def body(self) -> Region:
        return self.regions[0]

    @property
    def entry_block(self) -> Block:
        return self.body.entry


def iter_operations(op: Operation) -> Iterable[Operation]:
    """Yield an operation and every nested operation."""

    queue = [op]
    while queue:
        current = queue.pop(0)
        yield current
        for region in current.regions:
            for block in region.blocks:
                queue.extend(block.operations)

