"""Text printer for the mini MLIR/CIRCT IR."""

from __future__ import annotations

from io import StringIO

from .ir import FuncOp, ModuleOp, Operation


class Printer:
    """Render IR back to a readable textual form."""

    def __init__(self) -> None:
        self._buffer = StringIO()

    def print(self, op: Operation) -> str:
        self._print_operation(op, 0, top_level=True)
        return self._buffer.getvalue().rstrip() + "\n"

    def _writeln(self, text: str = "") -> None:
        self._buffer.write(text)
        self._buffer.write("\n")

    def _print_operation(self, op: Operation, indent: int, *, top_level: bool = False) -> None:
        custom = op.format()
        if custom is not None:
            self._writeln(("  " * indent) + custom)
            return
        if isinstance(op, ModuleOp):
            self._writeln("module {")
            for inner in op.body.operations:
                self._print_operation(inner, indent + 1)
            self._writeln("}")
            return
        if isinstance(op, FuncOp):
            self._print_func(op, indent)
            return
        self._writeln(("  " * indent) + self._format_simple_operation(op))

    def _print_func(self, func: FuncOp, indent: int) -> None:
        arg_text = ", ".join(f"{arg.name}: {arg.type}" for arg in func.entry_block.arguments)
        result_types = func.function_type.results
        if not result_types:
            result_text = ""
        elif len(result_types) == 1:
            result_text = f" -> {result_types[0]}"
        else:
            result_text = f" -> ({', '.join(str(item) for item in result_types)})"
        base_indent = "  " * indent
        self._writeln(f"{base_indent}func.func @{func.symbol_name}({arg_text}){result_text} {{")
        for block_index, block in enumerate(func.body.blocks):
            if block.label is not None:
                self._writeln(f"{base_indent}  ^{block.label}:")
            for op in block.operations:
                self._print_operation(op, indent + 2)
            if block_index != len(func.body.blocks) - 1 and block.is_empty():
                self._writeln()
        self._writeln(f"{base_indent}}}")

    def _format_simple_operation(self, op: Operation) -> str:
        if op.name in {"arith.constant", "hw.constant"}:
            return f"{op.result.name} = {op.name} {op.attributes['value']} : {op.attributes['type']}"
        if op.name in {"arith.addi", "arith.subi", "arith.muli", "comb.add", "comb.and", "comb.or", "comb.xor"}:
            lhs, rhs = op.operands
            result_name = f"{op.result.name} = " if op.result is not None else ""
            return f"{result_name}{op.name} {lhs.name}, {rhs.name} : {op.attributes['type']}"
        if op.name in {"arith.cmpi", "comb.icmp"}:
            lhs, rhs = op.operands
            op_type = op.attributes.get("operand_type", op.attributes.get("type"))
            return (
                f"{op.result.name} = {op.name} {op.attributes['predicate']}, "
                f"{lhs.name}, {rhs.name} : {op_type}"
            )
        if op.name == "comb.mux":
            sel, true_value, false_value = op.operands
            return (
                f"{op.result.name} = comb.mux {sel.name}, {true_value.name}, {false_value.name} "
                f": {op.attributes['type']}"
            )
        if op.name == "return":
            if not op.operands:
                return "return"
            return f"return {op.operands[0].name} : {op.attributes['type']}"
        if op.name == "cf.br":
            return f"cf.br ^{op.successors[0].label}"
        if op.name == "cf.cond_br":
            return (
                f"cf.cond_br {op.operands[0].name}, ^{op.successors[0].label}, "
                f"^{op.successors[1].label}"
            )
        if op.name == "hw.output":
            operands = ", ".join(value.name for value in op.operands)
            type_text = op.attributes.get("types")
            if type_text:
                rendered_types = ", ".join(str(item) for item in type_text)
                return f"hw.output {operands} : {rendered_types}"
            if len(op.operands) == 1 and "type" in op.attributes:
                return f"hw.output {operands} : {op.attributes['type']}"
            return f"hw.output {operands}"
        if op.name == "seq.compreg":
            result_name = f"{op.result.name} = " if op.result is not None else ""
            reset = op.attributes["reset"]
            reset_value = op.attributes["reset_value"]
            return (
                f"{result_name}seq.compreg {op.operands[0].name}, {op.operands[1].name} "
                f"reset {reset.name}, {reset_value.name} : {op.attributes['type']}"
            )
        operands = ", ".join(value.name for value in op.operands)
        result_name = f"{op.result.name} = " if op.result is not None else ""
        if "type" in op.attributes:
            return f"{result_name}{op.name} {operands} : {op.attributes['type']}".rstrip()
        return f"{result_name}{op.name} {operands}".rstrip()


def print_ir(op: Operation) -> str:
    """Convenience wrapper used by tests and experiments."""

    return Printer().print(op)

