"""Minimal parser for the MLIR and CIRCT surface used by the inputs."""

from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Callable, Optional

from .ir import Block, FuncOp, IntegerType, ModuleOp, Operation, Region, Type, Value, parse_type


class ParseError(ValueError):
    """Raised when the input uses unsupported syntax."""


_TOPLEVEL_PARSERS: dict[str, Callable[["Parser"], Operation]] = {}
_OPERATION_PARSERS: dict[str, Callable[["Parser", Optional[str], str, "_BodyContext"], Operation]] = {}


def register_toplevel_parser(prefix: str, callback: Callable[["Parser"], Operation]) -> None:
    _TOPLEVEL_PARSERS[prefix] = callback


def register_operation_parser(
    op_name: str,
    callback: Callable[["Parser", Optional[str], str, "_BodyContext"], Operation],
) -> None:
    _OPERATION_PARSERS[op_name] = callback


@dataclass
class _BodyContext:
    region: Region
    values: dict[str, Value]
    blocks: dict[str, Block]

    def get_value(self, name: str) -> Value:
        if not name.startswith("%"):
            raise ParseError(f"expected SSA value, got {name}")
        if name not in self.values:
            self.values[name] = Value(name, placeholder=True)
        return self.values[name]

    def define_value(self, name: str, value_type: Optional[Type]) -> Value:
        value = self.get_value(name)
        if value.owner is not None and not value.placeholder:
            raise ParseError(f"duplicate SSA definition for {name}")
        value.type = value_type
        value.placeholder = False
        return value

    def get_block(self, label: str) -> Block:
        if label.startswith("^"):
            label = label[1:]
        if label not in self.blocks:
            block = Block(label=label)
            self.blocks[label] = block
            self.region.append(block)
        return self.blocks[label]


class Parser:
    """Line-oriented parser for a compact MLIR-like subset."""

    _FUNC_RE = re.compile(r"func\.func\s+@([A-Za-z_][\w$]*)\((.*)\)\s*(?:->\s*(.*?))?\s*\{$")

    def __init__(self, source: str) -> None:
        self.lines = self._clean_lines(source)
        self.index = 0

    @staticmethod
    def _clean_lines(source: str) -> list[str]:
        lines: list[str] = []
        for raw in source.splitlines():
            stripped = raw.split("//", 1)[0].rstrip()
            if stripped.strip():
                lines.append(stripped.strip())
        return lines

    def eof(self) -> bool:
        return self.index >= len(self.lines)

    def peek(self) -> str:
        if self.eof():
            raise ParseError("unexpected end of input")
        return self.lines[self.index]

    def pop(self) -> str:
        line = self.peek()
        self.index += 1
        return line

    def parse(self) -> Operation:
        if self.eof():
            raise ParseError("input is empty")
        line = self.peek()
        if line == "module {":
            return self.parse_module()
        if line.startswith("func.func"):
            return self.parse_func()
        for prefix, callback in _TOPLEVEL_PARSERS.items():
            if line.startswith(prefix):
                return callback(self)
        raise ParseError(f"unsupported top-level construct: {line}")

    def parse_module(self) -> ModuleOp:
        if self.pop() != "module {":
            raise ParseError("expected module {")
        module = ModuleOp()
        while True:
            line = self.peek()
            if line == "}":
                self.pop()
                break
            if line.startswith("func.func"):
                module.body.append(self.parse_func())
                continue
            dispatched = False
            for prefix, callback in _TOPLEVEL_PARSERS.items():
                if line.startswith(prefix):
                    module.body.append(callback(self))
                    dispatched = True
                    break
            if dispatched:
                continue
            raise ParseError(f"unsupported top-level operation: {line}")
        return module

    def parse_func(self) -> FuncOp:
        line = self.pop()
        match = self._FUNC_RE.fullmatch(line)
        if match is None:
            raise ParseError(f"malformed function header: {line}")
        name = match.group(1)
        arg_text = match.group(2)
        result_text = match.group(3)
        arg_names: list[str] = []
        arg_types: list[Type] = []
        if arg_text.strip():
            for piece in self._split_csv(arg_text):
                arg_name, arg_type = piece.split(":", 1)
                arg_names.append(arg_name.strip())
                arg_types.append(parse_type(arg_type.strip()))
        result_types = self._parse_result_types(result_text)
        func = FuncOp(name, arg_names, arg_types, result_types)
        context = _BodyContext(
            region=func.body,
            values={arg.name: arg for arg in func.entry_block.arguments},
            blocks={},
        )
        current_block = func.entry_block
        while True:
            line = self.peek()
            if line == "}":
                self.pop()
                break
            if line.startswith("^") and line.endswith(":"):
                label = line[1:-1]
                self.pop()
                current_block = context.get_block(label)
                continue
            current_block.append(self.parse_operation(line, context))
            self.index += 1
        self._verify_no_unresolved_values(context)
        return func

    def parse_operation(self, line: str, context: _BodyContext) -> Operation:
        result_name: Optional[str] = None
        text = line
        if "=" in line:
            maybe_result, remainder = line.split("=", 1)
            if maybe_result.strip().startswith("%"):
                result_name = maybe_result.strip()
                text = remainder.strip()
        if not text:
            raise ParseError(f"malformed operation: {line}")
        op_name, _, rest = text.partition(" ")
        rest = rest.strip()
        if op_name in _OPERATION_PARSERS:
            return _OPERATION_PARSERS[op_name](self, result_name, rest, context)
        if op_name == "arith.constant":
            return self._parse_constant("arith.constant", result_name, rest, context)
        if op_name in {"arith.addi", "arith.subi", "arith.muli"}:
            return self._parse_binary(op_name, result_name, rest, context)
        if op_name == "arith.cmpi":
            return self._parse_cmpi(result_name, rest, context)
        if op_name == "return":
            return self._parse_return(rest, context)
        if op_name == "cf.br":
            return self._parse_br(rest, context)
        if op_name == "cf.cond_br":
            return self._parse_cond_br(rest, context)
        raise ParseError(f"unsupported operation: {op_name}")

    def _parse_constant(
        self,
        op_name: str,
        result_name: Optional[str],
        rest: str,
        context: _BodyContext,
    ) -> Operation:
        if result_name is None:
            raise ParseError(f"{op_name} must define a result")
        value_text, type_text = rest.split(":", 1)
        result_type = parse_type(type_text.strip())
        result = context.define_value(result_name, result_type)
        return Operation(
            op_name,
            results=[result],
            attributes={"value": int(value_text.strip()), "type": result_type},
        )

    def _parse_binary(
        self,
        op_name: str,
        result_name: Optional[str],
        rest: str,
        context: _BodyContext,
    ) -> Operation:
        if result_name is None:
            raise ParseError(f"{op_name} must define a result")
        operand_text, type_text = rest.split(":", 1)
        lhs_name, rhs_name = self._split_csv(operand_text)
        result_type = parse_type(type_text.strip())
        result = context.define_value(result_name, result_type)
        return Operation(
            op_name,
            operands=[context.get_value(lhs_name.strip()), context.get_value(rhs_name.strip())],
            results=[result],
            attributes={"type": result_type},
        )

    def _parse_cmpi(self, result_name: Optional[str], rest: str, context: _BodyContext) -> Operation:
        if result_name is None:
            raise ParseError("arith.cmpi must define a result")
        predicate, remainder = rest.split(",", 1)
        operand_text, type_text = remainder.rsplit(":", 1)
        lhs_name, rhs_name = self._split_csv(operand_text)
        operand_type = parse_type(type_text.strip())
        result = context.define_value(result_name, IntegerType(1))
        return Operation(
            "arith.cmpi",
            operands=[context.get_value(lhs_name.strip()), context.get_value(rhs_name.strip())],
            results=[result],
            attributes={"predicate": predicate.strip(), "operand_type": operand_type},
        )

    def _parse_return(self, rest: str, context: _BodyContext) -> Operation:
        if not rest:
            return Operation("return")
        operand_text, type_text = rest.split(":", 1)
        operand = context.get_value(operand_text.strip())
        return Operation("return", operands=[operand], attributes={"type": parse_type(type_text.strip())})

    def _parse_br(self, rest: str, context: _BodyContext) -> Operation:
        target = context.get_block(rest.strip())
        return Operation("cf.br", successors=[target])

    def _parse_cond_br(self, rest: str, context: _BodyContext) -> Operation:
        cond_name, true_label, false_label = self._split_csv(rest)
        return Operation(
            "cf.cond_br",
            operands=[context.get_value(cond_name.strip())],
            successors=[context.get_block(true_label.strip()), context.get_block(false_label.strip())],
        )

    def _parse_result_types(self, result_text: Optional[str]) -> list[Type]:
        if result_text is None or not result_text.strip():
            return []
        result_text = result_text.strip()
        if result_text.startswith("(") and result_text.endswith(")"):
            inner = result_text[1:-1].strip()
            if not inner:
                return []
            return [parse_type(piece.strip()) for piece in self._split_csv(inner)]
        return [parse_type(result_text)]

    def _verify_no_unresolved_values(self, context: _BodyContext) -> None:
        unresolved = [name for name, value in context.values.items() if value.placeholder and value.owner is None]
        if unresolved:
            raise ParseError(f"unresolved SSA values: {', '.join(sorted(unresolved))}")

    @staticmethod
    def _split_csv(text: str) -> list[str]:
        return [piece.strip() for piece in text.split(",") if piece.strip()]


def parse(source: str) -> Operation:
    """Parse the supported subset of textual IR."""

    return Parser(source).parse()

