"""Pass infrastructure and greedy folding used by the arithmetic sample."""

from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Optional

from .ir import Block, IntegerType, ModuleOp, Operation, Value


class Pass(ABC):
    """Base class for module passes."""

    @abstractmethod
    def run(self, module: ModuleOp) -> None:
        raise NotImplementedError


class PassManager:
    """Sequential pass manager."""

    def __init__(self) -> None:
        self._passes: list[Pass] = []

    def add_pass(self, the_pass: Pass) -> None:
        self._passes.append(the_pass)

    def run(self, module: ModuleOp) -> None:
        for the_pass in self._passes:
            the_pass.run(module)


class PatternRewriter:
    """Helper used by rewrite patterns."""

    def replace_with_constant(self, op: Operation, value: int, result_type: IntegerType) -> None:
        masked = result_type.mask(value)
        op.name = "arith.constant"
        op.attributes = {"value": masked, "type": result_type}
        for operand in list(op.operands):
            operand.uses = [(user, idx) for user, idx in operand.uses if user is not op]
        op.operands = []
        op.successors = []
        if op.result is not None:
            op.result.type = result_type

    def erase_if_unused(self, block: Block, op: Operation) -> bool:
        if op.has_side_effects or any(result.use_count for result in op.results):
            return False
        block.erase(op)
        return True


class RewritePattern(ABC):
    """Base class for a single op rewrite."""

    @abstractmethod
    def match_and_rewrite(self, op: Operation, rewriter: PatternRewriter) -> bool:
        raise NotImplementedError


class ConstantFoldPattern(RewritePattern):
    """Fold simple arithmetic operations with integer constants."""

    def match_and_rewrite(self, op: Operation, rewriter: PatternRewriter) -> bool:
        if op.name not in {"arith.addi", "arith.subi", "arith.muli", "arith.cmpi"}:
            return False
        if len(op.operands) != 2:
            return False
        lhs = _constant_value(op.operands[0])
        rhs = _constant_value(op.operands[1])
        if lhs is None or rhs is None:
            return False
        if op.name == "arith.cmpi":
            predicate = op.attributes.get("predicate")
            operand_type = op.attributes.get("operand_type")
            if not isinstance(operand_type, IntegerType):
                return False
            lhs_value = operand_type.as_signed(lhs) if predicate.startswith("s") else operand_type.mask(lhs)
            rhs_value = operand_type.as_signed(rhs) if predicate.startswith("s") else operand_type.mask(rhs)
            if predicate == "eq":
                folded = 1 if lhs_value == rhs_value else 0
            elif predicate == "ne":
                folded = 1 if lhs_value != rhs_value else 0
            elif predicate == "sgt":
                folded = 1 if lhs_value > rhs_value else 0
            elif predicate == "sge":
                folded = 1 if lhs_value >= rhs_value else 0
            elif predicate == "slt":
                folded = 1 if lhs_value < rhs_value else 0
            elif predicate == "sle":
                folded = 1 if lhs_value <= rhs_value else 0
            else:
                return False
            rewriter.replace_with_constant(op, folded, IntegerType(1))
            return True
        result_type = op.attributes.get("type")
        if not isinstance(result_type, IntegerType):
            return False
        if op.name == "arith.addi":
            folded = lhs + rhs
        elif op.name == "arith.subi":
            folded = lhs - rhs
        else:
            folded = lhs * rhs
        rewriter.replace_with_constant(op, folded, result_type)
        return True


class GreedyRewriteDriver:
    """Run patterns until a fixed point, cleaning up dead pure ops."""

    def __init__(self, patterns: list[RewritePattern]) -> None:
        self.patterns = patterns

    def run(self, module: ModuleOp) -> int:
        rewrites = 0
        changed = True
        rewriter = PatternRewriter()
        while changed:
            changed = False
            for op in list(_iter_nested_operations(module)):
                if op.parent is None:
                    continue
                for pattern in self.patterns:
                    if pattern.match_and_rewrite(op, rewriter):
                        rewrites += 1
                        changed = True
                        break
            for block in _iter_blocks(module):
                for op in list(block.operations):
                    if rewriter.erase_if_unused(block, op):
                        changed = True
        return rewrites


class ConstantFolding(Pass):
    """Canonical constant folder for the supported arithmetic subset."""

    def __init__(self) -> None:
        self._stats = {"num_folded": 0}

    def run(self, module: ModuleOp) -> None:
        driver = GreedyRewriteDriver([ConstantFoldPattern()])
        self._stats["num_folded"] = driver.run(module)

    def get_statistic(self, name: str) -> int:
        return int(self._stats.get(name, 0))


def _constant_value(value: Value) -> Optional[int]:
    owner = value.owner
    if not isinstance(owner, Operation):
        return None
    if owner.name not in {"arith.constant", "hw.constant"}:
        return None
    return int(owner.attributes["value"])


def _iter_nested_operations(module: ModuleOp):
    for block in _iter_blocks(module):
        for op in list(block.operations):
            yield op
            for region in op.regions:
                for inner_block in region.blocks:
                    for inner_op in list(inner_block.operations):
                        yield inner_op


def _iter_blocks(module: ModuleOp):
    yield module.body
    for top_level in module.body.operations:
        for region in top_level.regions:
            for block in region.blocks:
                yield block

