"""CIRCT hw dialect support."""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Sequence

from mlir.ir import Block, IntegerType, Operation, Region, Type, Value


class Direction(str, Enum):
    """Hardware port direction."""

    IN = "in"
    OUT = "out"


IntType = IntegerType


@dataclass(frozen=True)
class Port:
    """Hardware module port."""

    direction: Direction
    name: str
    type: Type

    @property
    def ssa_name(self) -> str:
        return self.name if self.name.startswith("%") else f"%{self.name}"

    @property
    def is_input(self) -> bool:
        return self.direction == Direction.IN

    @property
    def is_output(self) -> bool:
        return self.direction == Direction.OUT


class HWModuleOp(Operation):
    """Hardware module container."""

    def __init__(self, symbol_name: str, ports: Sequence[Port]) -> None:
        self._ports = list(ports)
        arguments = [Value(port.ssa_name, port.type) for port in self._ports if port.is_input]
        body = Region([Block(arguments=arguments)])
        super().__init__(
            "hw.module",
            attributes={"sym_name": symbol_name},
            regions=[body],
        )

    @property
    def symbol_name(self) -> str:
        return str(self.attributes["sym_name"])

    @property
    def ports(self) -> list[Port]:
        return list(self._ports)

    @property
    def body(self) -> Block:
        return self.regions[0].entry

    @property
    def input_ports(self) -> list[Port]:
        return [port for port in self._ports if port.is_input]

    @property
    def output_ports(self) -> list[Port]:
        return [port for port in self._ports if port.is_output]

    def get_input_argument(self, port_name: str) -> Value:
        normalized = port_name.removeprefix("%")
        for argument in self.body.arguments:
            if argument.name.removeprefix("%") == normalized:
                return argument
        raise KeyError(port_name)


class ConstantOp(Operation):
    """Hardware constant."""

    def __init__(self, value: int, value_type: Type, result: Value) -> None:
        super().__init__(
            "hw.constant",
            results=[result],
            attributes={"value": int(value), "type": value_type},
        )

    @property
    def value(self) -> int:
        return int(self.attributes["value"])

    @property
    def type(self) -> Type:
        return self.attributes["type"]


class OutputOp(Operation):
    """Module output terminator."""

    def __init__(self, operands: Sequence[Value], types: Sequence[Type]) -> None:
        attributes = {}
        types = list(types)
        if len(types) == 1:
            attributes["type"] = types[0]
        elif types:
            attributes["types"] = types
        super().__init__("hw.output", operands=list(operands), attributes=attributes)

