"""Cycle-accurate simulator for the supported CIRCT subset."""

from __future__ import annotations

from dataclasses import dataclass

from mlir.ir import IntegerType, Operation, Value

from .comb_dialect import CombOp
from .hw_dialect import ConstantOp, HWModuleOp, OutputOp
from .seq_dialect import CompRegOp


@dataclass
class TraceFrame:
    cycle: int
    inputs: dict[str, int]
    outputs: dict[str, int]
    registers: dict[str, int]


class CircuitSimulator:
    """Evaluate combinational logic and update seq.compreg state per cycle."""

    def __init__(self, module: HWModuleOp) -> None:
        self.module = module
        self.cycle = 0
        self.state = {
            reg.result.name: self._initial_register_value(reg)
            for reg in self._registers()
            if reg.result is not None
        }
        self.trace: list[TraceFrame] = []

    def reset(self) -> None:
        self.cycle = 0
        self.state = {
            reg.result.name: self._initial_register_value(reg)
            for reg in self._registers()
            if reg.result is not None
        }
        self.trace.clear()

    def simulate_combinational(self, inputs: dict[str, int]) -> dict[str, int]:
        env = self._evaluate(inputs, update_state=False)
        return self._collect_outputs(env)

    def step(self, inputs: dict[str, int]) -> dict[str, int]:
        env = self._evaluate(inputs, update_state=True)
        outputs = self._collect_outputs(env)
        frame = TraceFrame(
            cycle=self.cycle,
            inputs=dict(inputs),
            outputs=dict(outputs),
            registers=dict(self.state),
        )
        self.trace.append(frame)
        self.cycle += 1
        return outputs

    def run(self, sequence: list[dict[str, int]]) -> list[dict[str, int]]:
        return [self.step(inputs) for inputs in sequence]

    def get_register(self, name: str) -> int:
        normalized = name if name.startswith("%") else f"%{name}"
        return int(self.state[normalized])

    def _evaluate(self, inputs: dict[str, int], *, update_state: bool) -> dict[str, int]:
        env: dict[str, int] = {}
        for port, argument in zip(self.module.input_ports, self.module.body.arguments):
            raw_value = inputs.get(port.name, inputs.get(argument.name, 0))
            env[argument.name] = self._mask(port.type, int(raw_value))
            env[port.name] = env[argument.name]
        for reg in self._registers():
            if reg.result is None:
                continue
            value = int(self.state.get(reg.result.name, self._initial_register_value(reg)))
            env[reg.result.name] = value
            env[reg.result.name.removeprefix("%")] = value
        pending = list(self.module.body.operations)
        progress = True
        while pending and progress:
            progress = False
            next_pending: list[Operation] = []
            for op in pending:
                if isinstance(op, ConstantOp):
                    value = self._mask(op.type, op.value)
                    env[op.result.name] = value
                    env[op.result.name.removeprefix("%")] = value
                    progress = True
                    continue
                if isinstance(op, CompRegOp):
                    progress = True
                    continue
                if isinstance(op, CombOp):
                    try:
                        value = op.evaluate(env)
                    except KeyError:
                        next_pending.append(op)
                        continue
                    env[op.result.name] = value
                    env[op.result.name.removeprefix("%")] = value
                    progress = True
                    continue
                if isinstance(op, OutputOp):
                    if all(self._has_value(env, operand) for operand in op.operands):
                        progress = True
                        continue
                    next_pending.append(op)
                    continue
                raise ValueError(f"unsupported operation in simulator: {op.name}")
            pending = next_pending
        if pending:
            names = ", ".join(op.name for op in pending)
            raise ValueError(f"could not resolve circuit values for: {names}")
        if update_state:
            self._update_registers(env, inputs)
        return env

    def _update_registers(self, env: dict[str, int], inputs: dict[str, int]) -> None:
        for reg in self._registers():
            if reg.result is None:
                continue
            clock_names = [reg.clock.name, reg.clock.name.removeprefix("%")]
            clock_value = next((int(inputs[name]) for name in clock_names if name in inputs), 1)
            if not clock_value:
                continue
            next_value = self._lookup(env, reg.data)
            if reg.reset is not None and self._lookup(env, reg.reset):
                if reg.reset_value is not None:
                    next_value = self._lookup(env, reg.reset_value)
            self.state[reg.result.name] = reg.mask(next_value)

    def _collect_outputs(self, env: dict[str, int]) -> dict[str, int]:
        for op in self.module.body.operations:
            if isinstance(op, OutputOp):
                values = [self._lookup(env, operand) for operand in op.operands]
                outputs = {}
                for port, value in zip(self.module.output_ports, values):
                    outputs[port.name] = self._mask(port.type, value)
                return outputs
        return {}

    def _initial_register_value(self, reg: CompRegOp) -> int:
        reset_value = reg.reset_value
        if reset_value is None or reg.result is None:
            return 0
        owner = reset_value.owner
        if isinstance(owner, ConstantOp):
            return self._mask(reg.type, owner.value)
        return 0

    def _registers(self) -> list[CompRegOp]:
        return [op for op in self.module.body.operations if isinstance(op, CompRegOp)]

    @staticmethod
    def _has_value(env: dict[str, int], operand: Value) -> bool:
        return operand.name in env or operand.name.removeprefix("%") in env

    @staticmethod
    def _lookup(env: dict[str, int], operand: Value) -> int:
        for name in (operand.name, operand.name.removeprefix("%")):
            if name in env:
                return int(env[name])
        raise KeyError(operand.name)

    @staticmethod
    def _mask(value_type, value: int) -> int:
        if isinstance(value_type, IntegerType):
            return value_type.mask(value)
        return value

