"""CIRCT seq dialect support."""

from __future__ import annotations

from typing import Optional

from mlir.ir import IntegerType, Operation, Type, Value


def _normalize_value(item: Value | str | None, width: Optional[int] = None) -> Optional[Value]:
    if item is None:
        return None
    if isinstance(item, Value):
        return item
    value_type = IntegerType(width) if width is not None else None
    name = item if str(item).startswith("%") else f"%{item}"
    return Value(name, value_type=value_type, placeholder=True)


class CompRegOp(Operation):
    """Cycle-delayed register with optional reset semantics."""

    def __init__(
        self,
        data: Value | str | None = None,
        clock: Value | str | None = None,
        *,
        reset: Value | str | None = None,
        reset_value: Value | str | None = None,
        value_type: Optional[Type] = None,
        result: Optional[Value] = None,
        result_name: Optional[str] = None,
        width: Optional[int] = None,
        name: Optional[str] = None,
        input_signal: Optional[str] = None,
        initial_value: int = 0,
    ) -> None:
        if value_type is None and width is not None:
            value_type = IntegerType(width)
        if result is None and result_name is not None and value_type is not None:
            result = Value(result_name, value_type)
        if result is None and name is not None and value_type is not None:
            result = Value(name, value_type)
        self._shadow_value = int(initial_value)
        data_value = _normalize_value(data or input_signal, width)
        clock_value = _normalize_value(clock or "clk", width=None)
        if data_value is None or clock_value is None:
            raise ValueError("seq.compreg requires data and clock signals")
        super().__init__(
            "seq.compreg",
            operands=[data_value, clock_value],
            results=[result] if result is not None else [],
            attributes={
                "type": value_type,
                "reset": _normalize_value(reset, width=None),
                "reset_value": _normalize_value(reset_value, width=width),
            },
        )

    @property
    def type(self) -> Type:
        return self.attributes["type"]

    @property
    def data(self) -> Value:
        return self.operands[0]

    @property
    def clock(self) -> Value:
        return self.operands[1]

    @property
    def reset(self) -> Optional[Value]:
        return self.attributes.get("reset")

    @property
    def reset_value(self) -> Optional[Value]:
        return self.attributes.get("reset_value")

    def mask(self, value: int) -> int:
        if isinstance(self.type, IntegerType):
            return self.type.mask(value)
        return value

    def tick(self, env: dict[str, int]) -> int:
        names = [self.data.name, self.data.name.removeprefix("%")]
        for name in names:
            if name in env:
                next_value = int(env[name])
                break
        else:
            raise KeyError(self.data.name)
        if self.reset is not None:
            reset_names = [self.reset.name, self.reset.name.removeprefix("%")]
            reset_active = any(env.get(name, 0) for name in reset_names)
            if reset_active and self.reset_value is not None:
                reset_value_names = [self.reset_value.name, self.reset_value.name.removeprefix("%")]
                for name in reset_value_names:
                    if name in env:
                        next_value = int(env[name])
                        break
        self._shadow_value = self.mask(next_value)
        return self._shadow_value

    def get_value(self) -> int:
        return self._shadow_value

