"""CIRCT comb dialect support."""

from __future__ import annotations

from typing import Callable, Iterable, Optional, Sequence

from mlir.ir import IntegerType, Operation, Type, Value


def _to_value(item: Value | str, width: Optional[int] = None) -> Value:
    if isinstance(item, Value):
        return item
    value_type = IntegerType(width) if width is not None else None
    name = item if str(item).startswith("%") else f"%{item}"
    return Value(name, value_type=value_type, placeholder=True)


def _pick_env_value(env: dict[str, int], value: Value) -> int:
    names = [value.name, value.name.removeprefix("%")]
    for name in names:
        if name in env:
            return int(env[name])
    raise KeyError(value.name)


class CombOp(Operation):
    """Base class for combinational operations."""

    op_name = "comb.unknown"

    def __init__(
        self,
        operands: Sequence[Value | str],
        *,
        result: Optional[Value] = None,
        result_name: Optional[str] = None,
        value_type: Optional[Type] = None,
        width: Optional[int] = None,
        attributes: Optional[dict[str, object]] = None,
    ) -> None:
        if value_type is None and width is not None:
            value_type = IntegerType(width)
        results = []
        if result is not None:
            results = [result]
        elif result_name is not None and value_type is not None:
            results = [Value(result_name, value_type)]
        normalized = [_to_value(item, width) for item in operands]
        attrs = dict(attributes or {})
        if value_type is not None:
            attrs.setdefault("type", value_type)
        super().__init__(self.op_name, operands=normalized, results=results, attributes=attrs)

    @property
    def type(self) -> Type:
        return self.attributes["type"]

    def _mask(self, value: int) -> int:
        if isinstance(self.type, IntegerType):
            return self.type.mask(value)
        return value

    def evaluate(self, env: dict[str, int]) -> int:
        raise NotImplementedError


class BinaryCombOp(CombOp):
    """Two-input combinational operator."""

    def __init__(
        self,
        operands: Sequence[Value | str],
        *,
        result: Optional[Value] = None,
        result_name: Optional[str] = None,
        value_type: Optional[Type] = None,
        width: Optional[int] = None,
    ) -> None:
        if len(list(operands)) != 2:
            raise ValueError(f"{self.op_name} expects exactly two operands")
        super().__init__(
            operands,
            result=result,
            result_name=result_name,
            value_type=value_type,
            width=width,
        )

    def _apply(self, lhs: int, rhs: int) -> int:
        raise NotImplementedError

    def evaluate(self, env: dict[str, int]) -> int:
        lhs = _pick_env_value(env, self.operands[0])
        rhs = _pick_env_value(env, self.operands[1])
        return self._mask(self._apply(lhs, rhs))


class AddOp(BinaryCombOp):
    op_name = "comb.add"

    def _apply(self, lhs: int, rhs: int) -> int:
        return lhs + rhs


class SubOp(BinaryCombOp):
    op_name = "comb.sub"

    def _apply(self, lhs: int, rhs: int) -> int:
        return lhs - rhs


class MulOp(BinaryCombOp):
    op_name = "comb.mul"

    def _apply(self, lhs: int, rhs: int) -> int:
        return lhs * rhs


class AndOp(BinaryCombOp):
    op_name = "comb.and"

    def _apply(self, lhs: int, rhs: int) -> int:
        return lhs & rhs


class OrOp(BinaryCombOp):
    op_name = "comb.or"

    def _apply(self, lhs: int, rhs: int) -> int:
        return lhs | rhs


class XorOp(BinaryCombOp):
    op_name = "comb.xor"

    def _apply(self, lhs: int, rhs: int) -> int:
        return lhs ^ rhs


class ICmpOp(CombOp):
    """Integer compare."""

    op_name = "comb.icmp"

    def __init__(
        self,
        predicate: str,
        operands: Sequence[Value | str],
        *,
        result: Optional[Value] = None,
        result_name: Optional[str] = None,
        operand_type: Optional[Type] = None,
        width: Optional[int] = None,
    ) -> None:
        operand_type = operand_type or (IntegerType(width) if width is not None else None)
        super().__init__(
            operands,
            result=result,
            result_name=result_name,
            value_type=IntegerType(1),
            width=width,
            attributes={"predicate": predicate, "operand_type": operand_type},
        )

    def evaluate(self, env: dict[str, int]) -> int:
        lhs = _pick_env_value(env, self.operands[0])
        rhs = _pick_env_value(env, self.operands[1])
        predicate = self.attributes["predicate"]
        operand_type = self.attributes["operand_type"]
        if isinstance(operand_type, IntegerType) and predicate.startswith("s"):
            lhs = operand_type.as_signed(lhs)
            rhs = operand_type.as_signed(rhs)
        if predicate == "eq":
            return 1 if lhs == rhs else 0
        if predicate == "ne":
            return 1 if lhs != rhs else 0
        if predicate == "sgt":
            return 1 if lhs > rhs else 0
        if predicate == "sge":
            return 1 if lhs >= rhs else 0
        if predicate == "slt":
            return 1 if lhs < rhs else 0
        if predicate == "sle":
            return 1 if lhs <= rhs else 0
        raise ValueError(f"unsupported predicate {predicate}")


class MuxOp(CombOp):
    """Two-way mux."""

    op_name = "comb.mux"

    def __init__(
        self,
        operands: Sequence[Value | str],
        *,
        result: Optional[Value] = None,
        result_name: Optional[str] = None,
        value_type: Optional[Type] = None,
        width: Optional[int] = None,
    ) -> None:
        if len(list(operands)) != 3:
            raise ValueError("comb.mux expects select, true, false operands")
        super().__init__(
            operands,
            result=result,
            result_name=result_name,
            value_type=value_type,
            width=width,
        )

    def evaluate(self, env: dict[str, int]) -> int:
        select = _pick_env_value(env, self.operands[0])
        true_value = _pick_env_value(env, self.operands[1])
        false_value = _pick_env_value(env, self.operands[2])
        return self._mask(true_value if select else false_value)

