"""Explicit semantic rules for evaluating supported circuits."""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Optional

from circt.comb_dialect import CombOp
from circt.hw_dialect import ConstantOp, HWModuleOp, OutputOp
from circt.seq_dialect import CompRegOp
from mlir.ir import IntegerType, Operation, Value


def _lookup(env: dict[str, int], operand: Value) -> int:
    for name in (operand.name, operand.name.removeprefix("%")):
        if name in env:
            return int(env[name])
    raise KeyError(operand.name)


def _mask(value_type, value: int) -> int:
    if isinstance(value_type, IntegerType):
        return value_type.mask(value)
    return value


@dataclass
class TraceEvent:
    cycle: int
    rule: str
    op_name: str
    target: str
    value: int | str | None


@dataclass
class TraceFrame:
    cycle: int
    inputs: dict[str, int]
    outputs: dict[str, int]
    registers: dict[str, int]
    events: list[TraceEvent] = field(default_factory=list)


@dataclass
class SemanticState:
    cycle: int
    env: dict[str, int]
    registers: dict[str, int]
    outputs: dict[str, int]
    inputs: dict[str, int]
    events: list[TraceEvent] = field(default_factory=list)


class SemanticRule(ABC):
    """A single executable semantic rule."""

    name = "rule"

    @abstractmethod
    def matches(self, op: Operation) -> bool:
        raise NotImplementedError

    @abstractmethod
    def apply(self, op: Operation, state: SemanticState) -> bool:
        raise NotImplementedError

    def _record(self, state: SemanticState, op: Operation, target: str, value: int | str | None) -> None:
        state.events.append(TraceEvent(state.cycle, self.name, op.name, target, value))


class ConstantRule(SemanticRule):
    name = "constant"

    def matches(self, op: Operation) -> bool:
        return isinstance(op, ConstantOp)

    def apply(self, op: Operation, state: SemanticState) -> bool:
        assert isinstance(op, ConstantOp)
        value = _mask(op.type, op.value)
        state.env[op.result.name] = value
        state.env[op.result.name.removeprefix("%")] = value
        self._record(state, op, op.result.name, value)
        return True


class CombEvalRule(SemanticRule):
    name = "comb"

    def matches(self, op: Operation) -> bool:
        return isinstance(op, CombOp)

    def apply(self, op: Operation, state: SemanticState) -> bool:
        assert isinstance(op, CombOp)
        try:
            value = op.evaluate(state.env)
        except KeyError:
            return False
        state.env[op.result.name] = value
        state.env[op.result.name.removeprefix("%")] = value
        self._record(state, op, op.result.name, value)
        return True


class CompRegReadRule(SemanticRule):
    name = "compreg-read"

    def matches(self, op: Operation) -> bool:
        return isinstance(op, CompRegOp)

    def apply(self, op: Operation, state: SemanticState) -> bool:
        assert isinstance(op, CompRegOp)
        if op.result is None:
            return False
        current = int(state.registers.get(op.result.name, 0))
        state.env[op.result.name] = current
        state.env[op.result.name.removeprefix("%")] = current
        self._record(state, op, op.result.name, current)
        return True


class OutputRule(SemanticRule):
    name = "output"

    def __init__(self, module: HWModuleOp) -> None:
        self.module = module

    def matches(self, op: Operation) -> bool:
        return isinstance(op, OutputOp)

    def apply(self, op: Operation, state: SemanticState) -> bool:
        assert isinstance(op, OutputOp)
        try:
            values = [_lookup(state.env, operand) for operand in op.operands]
        except KeyError:
            return False
        for port, value in zip(self.module.output_ports, values):
            masked = _mask(port.type, value)
            state.outputs[port.name] = masked
            self._record(state, op, port.name, masked)
        return True


class CompRegWriteRule(SemanticRule):
    name = "compreg-write"

    def matches(self, op: Operation) -> bool:
        return isinstance(op, CompRegOp)

    def apply(self, op: Operation, state: SemanticState) -> bool:
        assert isinstance(op, CompRegOp)
        if op.result is None:
            return False
        clock_value = 1
        for name in (op.clock.name, op.clock.name.removeprefix("%")):
            if name in state.inputs:
                clock_value = int(state.inputs[name])
                break
        if not clock_value:
            self._record(state, op, op.result.name, state.registers.get(op.result.name, 0))
            return True
        next_value = _lookup(state.env, op.data)
        if op.reset is not None and _lookup(state.env, op.reset):
            if op.reset_value is not None:
                next_value = _lookup(state.env, op.reset_value)
        masked = op.mask(next_value)
        state.registers[op.result.name] = masked
        self._record(state, op, op.result.name, masked)
        return True


class StatefulCircuitExecutor:
    """Executes a hardware module using explicit semantic rules."""

    def __init__(self, module: HWModuleOp) -> None:
        self.module = module
        self.comb_rules: list[SemanticRule] = [
            ConstantRule(),
            CompRegReadRule(),
            CombEvalRule(),
            OutputRule(module),
        ]
        self.write_rule = CompRegWriteRule()
        self.cycle = 0
        self.registers = self._initial_registers()

    def reset(self) -> None:
        self.cycle = 0
        self.registers = self._initial_registers()

    def peek(self, inputs: dict[str, int]) -> TraceFrame:
        state = self._execute(inputs, commit=False)
        return TraceFrame(state.cycle, dict(inputs), dict(state.outputs), dict(state.registers), list(state.events))

    def step(self, inputs: dict[str, int]) -> TraceFrame:
        state = self._execute(inputs, commit=True)
        self.cycle += 1
        return TraceFrame(state.cycle, dict(inputs), dict(state.outputs), dict(state.registers), list(state.events))

    def _execute(self, inputs: dict[str, int], *, commit: bool) -> SemanticState:
        working_inputs = dict(inputs)
        env: dict[str, int] = {}
        for port, argument in zip(self.module.input_ports, self.module.body.arguments):
            raw_value = working_inputs.get(port.name, working_inputs.get(argument.name, 0))
            value = _mask(port.type, int(raw_value))
            env[argument.name] = value
            env[port.name] = value
        state = SemanticState(
            cycle=self.cycle,
            env=env,
            registers=dict(self.registers),
            outputs={},
            inputs=working_inputs,
        )
        pending = list(self.module.body.operations)
        applied_once: set[int] = set()
        progress = True
        while pending and progress:
            progress = False
            next_pending: list[Operation] = []
            for op in pending:
                matched = False
                for rule in self.comb_rules:
                    if not rule.matches(op):
                        continue
                    matched = True
                    if isinstance(rule, (ConstantRule, CompRegReadRule)) and id(op) in applied_once:
                        progress = True
                        break
                    if rule.apply(op, state):
                        progress = True
                        applied_once.add(id(op))
                        break
                    next_pending.append(op)
                    break
                if not matched:
                    raise ValueError(f"no semantic rule for {op.name}")
            pending = next_pending
        if pending:
            names = ", ".join(op.name for op in pending)
            raise ValueError(f"semantic execution stalled on: {names}")
        if commit:
            for op in self.module.body.operations:
                if self.write_rule.matches(op):
                    self.write_rule.apply(op, state)
            self.registers = dict(state.registers)
        return state

    def _initial_registers(self) -> dict[str, int]:
        registers: dict[str, int] = {}
        for op in self.module.body.operations:
            if not isinstance(op, CompRegOp) or op.result is None:
                continue
            value = 0
            if op.reset_value is not None and op.reset_value.owner is not None:
                owner = op.reset_value.owner
                if isinstance(owner, ConstantOp):
                    value = _mask(op.type, owner.value)
            registers[op.result.name] = value
        return registers

