"""Symbol and type analyses for the mini CIRCT/MLIR stack."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Iterable, Optional

from circt.hw_dialect import HWModuleOp
from mlir.ir import Block, FuncOp, ModuleOp, Operation, Type, Value


def _name_aliases(name: str) -> set[str]:
    aliases = {name}
    if name.startswith("%"):
        aliases.add(name.removeprefix("%"))
    elif not name.startswith("@") and not name.startswith("^"):
        aliases.add(f"%{name}")
        aliases.add(f"@{name}")
    if name.startswith("@"):
        aliases.add(name.removeprefix("@"))
    return aliases


@dataclass
class SymbolTableAnalysis:
    """Collects symbol-like definitions and resolves operand references."""

    root: Operation
    definitions: dict[str, Any] = field(default_factory=dict)
    references: list[str] = field(default_factory=list)
    unresolved: list[str] = field(default_factory=list)
    resolved_references: int = 0

    @classmethod
    def from_operation(cls, op: Operation) -> "SymbolTableAnalysis":
        analysis = cls(op)
        analysis._collect_definitions(op)
        analysis._collect_references(op)
        return analysis

    def resolve(self, name: str) -> Optional[Any]:
        for alias in _name_aliases(name):
            if alias in self.definitions:
                return self.definitions[alias]
        return None

    def resolve_many(self, names: Iterable[str]) -> list[Any]:
        resolved = []
        for name in names:
            value = self.resolve(name)
            if value is not None:
                resolved.append(value)
        return resolved

    def _define(self, name: str, target: Any) -> None:
        for alias in _name_aliases(name):
            self.definitions.setdefault(alias, target)

    def _collect_definitions(self, op: Operation) -> None:
        if isinstance(op, ModuleOp) or isinstance(op, FuncOp) or isinstance(op, HWModuleOp):
            sym_name = op.attributes.get("sym_name")
            if sym_name:
                self._define(f"@{sym_name}", op)
        if isinstance(op, HWModuleOp):
            for port in op.ports:
                port_name = port.ssa_name if port.is_input else port.name
                self._define(port_name, port)
                self._define(port.name, port)
        for region in op.regions:
            for block in region.blocks:
                if block.label is not None:
                    self._define(f"^{block.label}", block)
                for argument in block.arguments:
                    self._define(argument.name, argument)
        for result in op.results:
            self._define(result.name, result)
        for region in op.regions:
            for block in region.blocks:
                for inner in block.operations:
                    self._collect_definitions(inner)

    def _collect_references(self, op: Operation) -> None:
        for operand in op.operands:
            self.references.append(operand.name)
            if self.resolve(operand.name) is None:
                self.unresolved.append(operand.name)
            else:
                self.resolved_references += 1
        for successor in op.successors:
            if successor.label is None:
                continue
            label = f"^{successor.label}"
            self.references.append(label)
            if self.resolve(label) is None:
                self.unresolved.append(label)
            else:
                self.resolved_references += 1
        for region in op.regions:
            for block in region.blocks:
                for inner in block.operations:
                    self._collect_references(inner)


@dataclass
class TypeAnalysis:
    """Tracks the resolved types of ports, block args, and SSA values."""

    root: Operation
    value_types: dict[str, Type] = field(default_factory=dict)
    errors: list[str] = field(default_factory=list)

    @classmethod
    def from_operation(cls, op: Operation) -> "TypeAnalysis":
        analysis = cls(op)
        analysis._collect(op)
        analysis._verify(op)
        return analysis

    def resolve(self, name: str) -> Optional[Type]:
        for alias in _name_aliases(name):
            if alias in self.value_types:
                return self.value_types[alias]
        return None

    def _record(self, name: str, value_type: Type) -> None:
        for alias in _name_aliases(name):
            self.value_types.setdefault(alias, value_type)

    def _collect(self, op: Operation) -> None:
        if isinstance(op, HWModuleOp):
            for port in op.ports:
                port_name = port.ssa_name if port.is_input else port.name
                self._record(port_name, port.type)
                self._record(port.name, port.type)
        for region in op.regions:
            for block in region.blocks:
                for argument in block.arguments:
                    if argument.type is not None:
                        self._record(argument.name, argument.type)
        for result in op.results:
            if result.type is not None:
                self._record(result.name, result.type)
        for region in op.regions:
            for block in region.blocks:
                for inner in block.operations:
                    self._collect(inner)

    def _verify(self, op: Operation) -> None:
        for operand in op.operands:
            if operand.type is None:
                self.errors.append(f"{op.name} uses untyped operand {operand.name}")
        for result in op.results:
            if result.type is None:
                self.errors.append(f"{op.name} defines untyped result {result.name}")
        for region in op.regions:
            for block in region.blocks:
                for inner in block.operations:
                    self._verify(inner)

