"""Kimulator: trace-oriented semantic execution for supported circuits."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Iterable

from circt import CircuitSimulator, parse_circuit
from circt.hw_dialect import HWModuleOp

from .semantics import StatefulCircuitExecutor, TraceEvent, TraceFrame


@dataclass
class KimulatorTrace:
    """Stores per-cycle semantic frames."""

    frames: list[TraceFrame] = field(default_factory=list)

    def append(self, frame: TraceFrame) -> None:
        self.frames.append(frame)

    @property
    def cycle_count(self) -> int:
        return len(self.frames)

    @property
    def event_count(self) -> int:
        return sum(len(frame.events) for frame in self.frames)

    def flatten_events(self) -> list[TraceEvent]:
        events: list[TraceEvent] = []
        for frame in self.frames:
            events.extend(frame.events)
        return events


class KimulatorTraceEngine:
    """Rule-driven execution engine that retains an explicit trace."""

    def __init__(self, module: HWModuleOp) -> None:
        self.module = module
        self.executor = StatefulCircuitExecutor(module)
        self.trace = KimulatorTrace()

    def reset(self) -> None:
        self.executor.reset()
        self.trace = KimulatorTrace()

    def peek(self, inputs: dict[str, int]) -> TraceFrame:
        return self.executor.peek(inputs)

    def step(self, inputs: dict[str, int]) -> TraceFrame:
        frame = self.executor.step(inputs)
        self.trace.append(frame)
        return frame

    def run(self, sequence: Iterable[dict[str, int]]) -> KimulatorTrace:
        for inputs in sequence:
            self.step(dict(inputs))
        return self.trace


class Kimulator:
    """High-level semantic interface with convenient simulation helpers."""

    def __init__(self, module: HWModuleOp) -> None:
        self.module = module
        self.engine = KimulatorTraceEngine(module)
        self.reference = CircuitSimulator(module)

    @classmethod
    def from_source(cls, source: str) -> "Kimulator":
        module = parse_circuit(source)
        if not isinstance(module, HWModuleOp):
            raise TypeError("Kimulator expects a top-level hw.module")
        return cls(module)

    def reset(self) -> None:
        self.engine.reset()
        self.reference.reset()

    def simulate_combinational(self, inputs: dict[str, int]) -> dict[str, int]:
        frame = self.engine.peek(inputs)
        return frame.outputs

    def step(self, inputs: dict[str, int]) -> dict[str, int]:
        frame = self.engine.step(inputs)
        reference_outputs = self.reference.step(inputs)
        if frame.outputs != reference_outputs:
            raise AssertionError("semantic execution diverged from the circuit simulator")
        return frame.outputs

    def run(self, sequence: Iterable[dict[str, int]]) -> KimulatorTrace:
        for inputs in sequence:
            self.step(dict(inputs))
        return self.engine.trace

    @property
    def trace(self) -> KimulatorTrace:
        return self.engine.trace

